fun bfs(graph: List<List<Int>>, startNode: Int): MutableList<Int> {
    // Create an empty list to store the visited nodes
    val visited = MutableList(graph.size) { -1 }

    // Create an empty queue to store the nodes to be visited
    val queue = MutableList<Int>()

    // Mark the start node as visited
    visited[startNode] = 0

    // Add the start node to the queue
    queue.add(startNode)

    // Traverse the graph
    while (queue.isNotEmpty()) {
        // Get the next node to be visited
        val currentNode = queue.removeAt(0)

        // Traverse all the neighbors of the current node
        for (neighbor in graph[currentNode]) {
            // If the neighbor is not visited, mark it as visited and add it to the queue
            if (visited[neighbor] == -1) {
                visited[neighbor] = 0
                queue.add(neighbor)
            }
        }
    }

    // Return the list of visited nodes
    return visited
}

