namespace WordCount
{
    class Program
    {
        static void Main(string[] args)
        {
            // Prompt the user to input a sentence
            Console.Write("Please enter a sentence: ");
            string userInput = Console.ReadLine();

            // Use a StringBuilder to build the word list and count words efficiently
            var wordBuilder = new System.Text.StringBuilder();
            int wordCount = 0;

            // Split the sentence into words using a regular expression to handle special characters and multiple spaces
            foreach (var match in Regex.Matches(userInput, @"\w+\s*"))
            {
                wordBuilder.Append(match.Value);
                wordBuilder.Append(" ");
                wordCount++;
            }

            // Remove the extra space at the end of the StringBuilder
            string words = wordBuilder.ToString().TrimEnd();

            // Display the total count of words in the sentence
            Console.WriteLine($"The sentence '{userInput}' contains {wordCount} words. The words are: {words}");
        }
    }
}
```

This C# program prompts the user to input a sentence and then displays the total count of words in that sentence. It uses a `StringBuilder` to build the list of words efficiently and a regular expression to handle special characters and multiple spaces between words. The variable names are meaningful and the code is organized in a clean and easy-to-read style.

