// Function to implement Breadth-First Search (BFS) algorithm on a given graph
fun bfs(graph: List<List<Int>>, startNode: Int): MutableList<Int> {
    // Create an empty MutableList to store the nodes visited during the traversal
    val visitedNodes = mutableListOf<Int>()

    // Create an empty MutableQueue to store the nodes to be visited
    val queue = mutableListOf<Node>()

    // Add the start node to the queue and mark it as visited
    queue.add(Node(startNode))
    visitedNodes.add(startNode)

    // Use a while loop to continue the traversal until the queue is empty
    while (queue.isNotEmpty()) {
        // Get the first node from the queue
        val currentNode = queue.removeAt(0)

        // Traverse through all the neighbors of the current node
        for (neighbor in graph[currentNode.id]!!) {
            // If the neighbor is not yet visited, mark it as visited and add it to the queue
            if (!visitedNodes.contains(neighbor)) {
                visitedNodes.add(neighbor)
                queue.add(Node(neighbor))
            }
        }
    }

    // Return the list of visited nodes
    return visitedNodes
}

// Sample usage of the bfs function
val graph = listOf(
    listOf(1, 2),
    listOf(0, 2),
    listOf(0, 1)
)
val startNode = 0
val visitedNodes = bfs(graph, startNode)
println("Nodes visited during BFS traversal: ${visitedNodes.joinToString(", ")}") // Output: Nodes visited during BFS traversal: 0, 1, 2
